s.push(new A.ab("\u041f\u0430\u043f\u043a\u0430 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0430","\u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u043f\u0430\u043f\u043a\u0443 \u043d\u0430 \u044d\u0442\u0430\u043f\u0435 \xab\u0421\u0432\u0435\u0440\u043a\u0430\xbb \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0437\u0432\u0435\u0437\u0434\u0443 \xab\u0411\u0443\u0434\u0443 \u0440\u0435\u0434\u0430\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c\xbb. \u0415\u0441\u043b\u0438 \u043f\u0430\u043f\u043a\u0430 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u0430, \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u0437\u0432\u0435\u0437\u0434\u0443. \u0415\u0441\u043b\u0438 \u043f\u0430\u043f\u043a\u0430 \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0430 \u0437\u0430 \u0434\u0440\u0443\u0433\u0438\u043c \u0440\u0435\u0434\u0430\u043a\u0442\u043e\u0440\u043e\u043c, \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u0435\u0433\u043e \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0442\u044c \u0435\u0451 \u0438\u043b\u0438 \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044c \u043a \u043c\u043e\u0434\u0435\u0440\u0430\u0442\u043e\u0440\u0443."))
s.push(new A.ab("\u041a\u0430\u043a \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u0435\u0440\u0435\u0441\u043d\u044f\u0442\u044c \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0443?","\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \xab\u041d\u0443\u0436\u043d\u0430 \u043f\u0435\u0440\u0435\u0441\u044a\u0451\u043c\u043a\u0430\xbb \u0432 \u0437\u0430\u043f\u0438\u0441\u0438 \u043d\u0430 \u0441\u0432\u0435\u0440\u043a\u0435. \u041d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u043d\u044b\u0439 \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444 \u0443\u0432\u0438\u0434\u0438\u0442 \u0437\u0430\u0434\u0430\u043d\u0438\u0435 \u043d\u0430 \u0413\u043b\u0430\u0432\u043d\u043e\u0439. \u041f\u043e\u0441\u043b\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0441\u043d\u0438\u043c\u043a\u0430 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0437\u0430\u043f\u0438\u0441\u044c \u0441\u043d\u043e\u0432\u0430 \u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u0435 \u0441\u0432\u0435\u0440\u043a\u0443."))
s.push(new A.ab("\u0417\u0430\u043f\u0438\u0441\u044c \u043d\u0435 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443","\u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u043e\u0435 \u0432 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0435 \u043f\u043e\u043b\u0435 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0437\u0430\u0433\u043b\u0430\u0432\u0438\u0435, \u043f\u043e\u043b\u043e\u0447\u043d\u044b\u0435 \u0448\u0438\u0444\u0440\u044b, \u0438\u043d\u0432\u0435\u043d\u0442\u0430\u0440\u043d\u044b\u0435 \u043d\u043e\u043c\u0435\u0440\u0430 \u0438 \u043c\u0435\u0441\u0442\u0430 \u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f. \u0415\u0441\u043b\u0438 \u043d\u0443\u0436\u043d\u0430 \u043f\u0435\u0440\u0435\u0441\u044a\u0451\u043c\u043a\u0430, \u0434\u043e\u0436\u0434\u0438\u0442\u0435\u0441\u044c \u043d\u043e\u0432\u043e\u0433\u043e \u0441\u043d\u0438\u043c\u043a\u0430 \u0438 \u0437\u0430\u0442\u0435\u043c \u0443\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0437\u0430\u043f\u0438\u0441\u044c."))
s.push(new A.ab("\u041a\u0430\u043a \u0438\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0437\u0430\u043f\u0438\u0441\u044c \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438?","\u0415\u0441\u043b\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430 \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0430\u043f\u0438\u0441\u044c \u0438 \u043f\u0430\u043f\u043a\u0430 \u0435\u0449\u0451 \u043d\u0430 \u0441\u0432\u0435\u0440\u043a\u0435, \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443 \u0441 \u0437\u0430\u043f\u0438\u0441\u0438. \u0415\u0441\u043b\u0438 \u0443\u0436\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430 \u0432\u0441\u044f \u043f\u0430\u043f\u043a\u0430, \u0432\u043e\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439\u0442\u0435\u0441\u044c \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u043e\u043c \u043d\u0430 \u0441\u0432\u0435\u0440\u043a\u0443, \u043a\u043e\u0433\u0434\u0430 \u043e\u043d \u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d, \u0438\u043b\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u043c\u043e\u0434\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043f\u0430\u043f\u043a\u0443."))
