if(r.db)s.push(new A.ab("\u041e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430\u0441\u044c \u0438\u043b\u0438 \u043e\u0441\u0442\u0430\u043b\u0438\u0441\u044c \u043e\u0448\u0438\u0431\u043a\u0438","\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435, \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0430 \u043b\u0438 \u0441\u044a\u0451\u043c\u043a\u0430 \u043f\u0430\u043f\u043a\u0438, \u0438 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \xab\u041e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430\xbb. \u0415\u0441\u043b\u0438 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u0435 \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u043e\u0441\u044c \u0441 \u043e\u0448\u0438\u0431\u043a\u0430\u043c\u0438, \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u041f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u044c \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0443\xbb. \u0415\u0441\u043b\u0438 \u0437\u0430\u043f\u0443\u0441\u043a \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d, \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0421\u043a\u0430\u043d\u0435\u0440\u0430."))
else s.push(new A.ab("\u0421\u044a\u0451\u043c\u043a\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0430. \u041a\u0430\u043a \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0443?","\u041f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u043d\u043e\u043c\u0435\u0440 \u043f\u0430\u043f\u043a\u0438 \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0442\u043e\u0440\u0443. \u041e\u043d \u043e\u0442\u043a\u0440\u043e\u0435\u0442 \xab\u041e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430\xbb \u0432 \u0440\u0435\u0436\u0438\u043c\u0435 \u043e\u0444\u043e\u0440\u043c\u0438\u0442\u0435\u043b\u044f \u0438 \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u0435. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442, \u043a\u043e\u0433\u0434\u0430 \u043e\u043d \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0432 \u043f\u0430\u043f\u043a\u0435."))
s.push(new A.ab("\u041f\u043e\u0441\u043b\u0435 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043e\u0441\u0442\u0430\u043b\u043e\u0441\u044c \xab\u0422\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430\xbb","\u0421\u0432\u0435\u0440\u044c\u0442\u0435 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u043d\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442 \u0441\u043e \u0441\u043d\u0438\u043c\u043a\u0430\u043c\u0438 \u0438 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0438 \u043e\u0447\u0438\u0441\u0442\u0438\u0442\u044c\xbb. \u0415\u0441\u043b\u0438 \u0447\u0430\u0441\u0442\u044c \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445 \u0441\u043d\u0438\u043c\u043a\u043e\u0432 \u043d\u0435 \u0443\u0434\u0430\u043b\u0438\u043b\u0430\u0441\u044c, \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0437\u0430\u043f\u0438\u0441\u044c \u0441\u043d\u043e\u0432\u0430 \u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0435 \u043e\u0447\u0438\u0441\u0442\u043a\u0443."))
